-- Inserts the JSON payloads the iOS app actually produces (generated by the Swift test
-- SchemaFixtureTests) as the owning user, exactly like PostgREST would, then exports the rows
-- back as JSON for the Swift decoder test. Fails if any JSON key has no matching column.
\set ON_ERROR_STOP on
\set QUIET on
insert into auth.users (id) values ('11111111-1111-4111-8111-111111111111');
create temp table fixtures (entity text primary key, ord int, payload jsonb);
grant select on fixtures to authenticated;
\copy fixtures (entity, ord, payload) from 'fixtures.tsv'

do $$
declare r record; bad text;
begin
  for r in select * from fixtures order by ord loop
    select string_agg(k, ', ') into bad from jsonb_object_keys(r.payload) k
      where k not in (select column_name from information_schema.columns where table_schema = 'public' and table_name = r.entity);
    if bad is not null then raise exception 'FAIL % has JSON keys without columns: %', r.entity, bad; end if;
  end loop;
  raise notice 'PASS every JSON key maps to a column';
end $$;

select set_config('request.jwt.claims', '{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}', false);
set role authenticated;
do $$
declare r record; n int;
begin
  for r in select * from fixtures order by ord loop
    execute format('insert into public.%I select * from jsonb_populate_record(null::public.%I, $1)', r.entity, r.entity) using r.payload;
    execute format('select count(*) from public.%I', r.entity) into n;
    if n <> 1 then raise exception 'FAIL % not readable after insert', r.entity; end if;
  end loop;
  raise notice 'PASS all fixtures inserted and readable by owner under RLS';
end $$;
reset role;
